parameters.jsCode:
// Aggregate ad performance from all platforms
const metaData = $('Fetch Meta Ads Performance').item.json;
const googleData = $('Fetch Google Ads Performance').item.json;

// Process Meta campaigns
const metaCampaigns = (metaData.data || []).map(c => {
  const conversions = (c.actions || []).find(a => a.action_type === 'offsite_conversion');
  return {
    platform: 'meta',
    campaign_id: c.campaign_id,
    campaign_name: c.campaign_name,
    spend: parseFloat(c.spend || 0),
    impressions: parseInt(c.impressions || 0),
    clicks: parseInt(c.clicks || 0),
    conversions: parseInt(conversions?.value || 0),
    ctr: parseFloat(c.ctr || 0),
    cpc: parseFloat(c.cpc || 0),
    cpa: conversions?.value > 0 ? parseFloat(c.spend) / parseInt(conversions.value) : null
  };
});

// Process Google campaigns
const googleCampaigns = (googleData.results || []).map(r => {
  const m = r.metrics || {};
  return {
    platform: 'google',
    campaign_id: r.campaign?.id,
    campaign_name: r.campaign?.name,
    spend: (parseInt(m.costMicros || 0)) / 1000000,
    impressions: parseInt(m.impressions || 0),
    clicks: parseInt(m.clicks || 0),
    conversions: parseFloat(m.conversions || 0),
    ctr: m.impressions > 0 ? (m.clicks / m.impressions * 100) : 0,
    cpc: m.clicks > 0 ? (parseInt(m.costMicros || 0) / 1000000 / m.clicks) : 0,
    cpa: m.conversions > 0 ? (parseInt(m.costMicros || 0) / 1000000 / m.conversions) : null
  };
});

const allCampaigns = [...metaCampaigns, ...googleCampaigns];
const totalSpend = allCampaigns.reduce((sum, c) => sum + c.spend, 0);
const totalConversions = allCampaigns.reduce((sum, c) => sum + (c.conversions || 0), 0);

return {
  json: {
    campaigns: allCampaigns,
    summary: {
      total_campaigns: allCampaigns.length,
      total_spend: totalSpend,
      total_conversions: totalConversions,
      avg_cpa: totalConversions > 0 ? totalSpend / totalConversions : null
    },
    daily_budget: parseFloat($env.DAILY_AD_BUDGET || 100),
    target_cpa: parseFloat($env.TARGET_CPA || 20)
  }
};

const perfData = $('Aggregate Performance').item.json;
const aiResponse = $input.item.json.message.content;
let optimization;
try { optimization = JSON.parse(aiResponse); } catch (e) { optimization = { error: 'Parse failed' }; }

return {
  json: {
    report_type: 'ads_optimization',
    generated_at: new Date().toISOString(),
    agent_id: 'media-buyer',
    workflow_id: 'WF-ADS-OPTIMIZE',
    performance_summary: perfData.summary,
    optimization,
    has_critical_alerts: (optimization.anomalies || []).some(a => a.severity === 'critical'),
    has_alerts: (optimization.alerts || []).length > 0
  }
};

